#!/usr/bin/env python3

import json
import sys
from pathlib import Path

import bpy
from io_scene_fbx import parse_fbx


def reset_scene() -> None:
    bpy.ops.wm.read_factory_settings(use_empty=True)


def add_empty(name: str, parent=None):
    obj = bpy.data.objects.new(name, None)
    bpy.context.scene.collection.objects.link(obj)
    obj.parent = parent
    return obj


def add_material(name: str, color):
    material = bpy.data.materials.new(name)
    material.diffuse_color = (*color, 1.0)
    material.use_nodes = True
    principled = material.node_tree.nodes.get("Principled BSDF")
    principled.inputs["Base Color"].default_value = (*color, 1.0)
    return material


def add_cube(name: str, parent, location, materials):
    bpy.ops.mesh.primitive_cube_add(size=1.0, location=location)
    obj = bpy.context.object
    obj.name = name
    obj.parent = parent
    for material in materials:
        obj.data.materials.append(material)
    if len(materials) > 1:
        for index, polygon in enumerate(obj.data.polygons):
            polygon.material_index = index % len(materials)
    return obj


def export_fbx(path: Path) -> None:
    bpy.ops.export_scene.fbx(
        filepath=path.as_posix(),
        use_selection=False,
        object_types={"EMPTY", "MESH"},
        use_custom_props=True,
        axis_forward="-Z",
        axis_up="Y",
        bake_anim=False,
    )


def create_synthetic(path: Path) -> None:
    reset_scene()
    root = add_empty("Root")
    line = add_empty("TreatmentLine", root)
    equipment = add_empty("Equipment", line)
    steel = add_material("Pump Steel", (0.12, 0.42, 0.78))
    accent = add_material("Pump Accent", (0.92, 0.46, 0.08))
    tank_color = add_material("Tank Green", (0.18, 0.62, 0.32))

    pump = add_cube(
        "Primary Pump",
        equipment,
        (2.0, 1.0, 0.5),
        [steel, accent],
    )
    pump["EquipmentTag"] = "P-101"
    pump["DesignFlow"] = 12.5
    pump["BusinessArea"] = "Treatment"

    for name, location in (
        ("Pump Instance A", (4.0, 1.0, 0.5)),
        ("Pump Instance B", (6.0, 1.0, 0.5)),
    ):
        instance = bpy.data.objects.new(name, pump.data)
        bpy.context.scene.collection.objects.link(instance)
        instance.parent = equipment
        instance.location = location
        instance["InstanceOf"] = "Primary Pump"

    tank = add_cube(
        "Buffer Tank",
        equipment,
        (8.0, 2.0, 0.75),
        [tank_color],
    )
    tank["EquipmentTag"] = "T-201"
    tank["BusinessArea"] = "Storage"
    export_fbx(path)


def create_empty(path: Path) -> None:
    reset_scene()
    add_empty("Root")
    export_fbx(path)


def ascii_property(value, type_code: str) -> str:
    if type_code == "S":
        text = value.decode("utf-8").replace("\x00\x01", "::")
        return json.dumps(text, ensure_ascii=True)
    if type_code == "B":
        return "T" if value else "F"
    if type_code in {"f", "i", "d", "l", "b"}:
        items = []
        for item in value:
            if type_code == "b":
                items.append("T" if item else "F")
            elif isinstance(item, float):
                items.append(format(item, ".17g"))
            else:
                items.append(str(item))
        return f"*{len(value)} {{ a: {','.join(items)} }}"
    if isinstance(value, float):
        return format(value, ".17g")
    if isinstance(value, bytes):
        return json.dumps(value.decode("latin1"))
    return str(value)


def write_ascii_element(output, element, depth: int, index: int) -> None:
    name = element.id.decode("utf-8")
    properties = [
        ascii_property(value, chr(type_code))
        for value, type_code in zip(element.props, element.props_type)
    ]
    indent = "    " * depth
    output.write(f"{indent}{name}:")
    if properties:
        output.write(f" {','.join(properties)}")
    if element.elems:
        output.write(" {\n")
        for child_index, child in enumerate(element.elems):
            write_ascii_element(output, child, depth + 1, child_index)
        output.write(f"{indent}}}\n")
    else:
        output.write("\n")


def write_ascii(binary_path: Path, ascii_path: Path) -> None:
    document, _version = parse_fbx.parse(
        binary_path.as_posix(),
        use_namedtuple=True,
    )
    with ascii_path.open("w", encoding="ascii", newline="\n") as output:
        output.write("; FBX 7.4.0 project file\n")
        output.write("; Generated by ICE3 from a synthetic scene.\n")
        for index, element in enumerate(document.elems):
            write_ascii_element(output, element, 0, index)


def write_truncated(binary_path: Path, output_path: Path) -> None:
    content = binary_path.read_bytes()
    objects = content.find(b"Objects")
    if objects < 0:
        raise RuntimeError("unable to locate Objects section")
    output_path.write_bytes(content[:objects + 96])


def main(directory: str) -> None:
    root = Path(directory)
    root.mkdir(parents=True, exist_ok=True)
    binary = root / "synthetic-binary.fbx"
    create_synthetic(binary)
    write_ascii(binary, root / "synthetic-ascii.fbx")
    create_empty(root / "empty.fbx")
    write_truncated(binary, root / "truncated.fbx")


if __name__ == "__main__":
    script_args = (
        sys.argv[sys.argv.index("--") + 1:]
        if "--" in sys.argv
        else sys.argv[1:]
    )
    if len(script_args) != 1:
        raise SystemExit("usage: generate-synthetic-fbx.py OUTPUT_DIRECTORY")
    main(script_args[0])
